<script lang="ts">
  import {onMount} from 'svelte';import DirectoryView from './DirectoryView.svelte';import AdvancedDownloadOptions from './AdvancedDownloadOptions.svelte';import Icon from './Icon.svelte';import {rpc,errorText,type DownloadInput,type DownloadPreview} from '../lib/api';import {modal} from '../lib/ui';
  let {home,url,filename,offerId,browserRequest=false,onclose,onstarted}:{home:string;url:string;filename:string;offerId?:string;browserRequest?:boolean;onclose:()=>void;onstarted:()=>void}=$props();let directory=$state('');let name=$state('');let source=$state('');let busy=$state(false);let error=$state('');let preview=$state<DownloadPreview|null>(null);let approved=$state(false);let confirmDirect=$state(false);let method=$state('GET');let headerText=$state('');let body=$state('');let reveal=$state(false);let useCapture=$state(true);let checked=$state(false);
  $effect(()=>{directory=home;name=filename;source=url;approved=false;confirmDirect=false;preview=null;checked=false;useCapture=!!offerId;method='GET';headerText='';body='';});
  const captured=$derived(useCapture&&!!offerId&&source===url);
  function input():DownloadInput {const headers=headerText.split('\n').filter(l=>l.trim()).map(line=>{const i=line.indexOf(':');if(i<1)throw new Error('Use one Header-Name: value per line.');return{name:line.slice(0,i).trim(),value:line.slice(i+1).trim()};});return {url:source,allowAuthentication:approved,browserRequest,confirmDirect,...(captured?{offerId}:{method,headers,...(method==='POST'?{body}:{})})};}
  let revision=0;
  async function inspect(){const ticket=revision;error='';checked=false;try{const result=await rpc('download_preview',input());if(ticket===revision){preview=result;checked=true;}}catch(e){if(ticket===revision){preview=null;error=errorText(e);}}}
  onMount(()=>{void inspect();return()=>{if(offerId)void rpc('download_discard',{id:offerId}).catch(()=>{});headerText='';body='';};});
  async function start(){busy=true;error='';try{await rpc('download_start',{...input(),directory,filename:name});onstarted();onclose();}catch(e){error=errorText(e);}finally{busy=false;}}
  function changed(){revision++;approved=false;checked=false;preview=null;}
</script>
<div class="modal-shade" role="presentation"><dialog class="destination-dialog" use:modal aria-label="Download to Server" oncancel={e=>{e.preventDefault();if(!busy)onclose();}}>
  <header><span class="app-mark"><Icon name="downloads" size={24}/></span><div><h2>Download to Server</h2><p class="muted">The Linux server fetches this file directly.</p></div><span class="spacer"></span><button class="icon-button" disabled={busy} onclick={onclose} aria-label="Close"><Icon name="close"/></button></header>
  <label class="download-url-label">HTTP/HTTPS URL<input bind:value={source} oninput={changed} aria-label="Download URL"/></label>
  <DirectoryView initial={home} foldersOnly onpath={p=>directory=p}/>
  <div class="destination-fields"><label>Filename<input bind:value={name}/></label><p class="muted">Remote destination: <strong>{directory}/{name}</strong></p><details class="advanced-download" open={!!offerId}><summary>Advanced Download Options</summary>
  {#if offerId}<label class="checkbox"><input type="checkbox" bind:checked={useCapture} onchange={changed}/> Use captured browser request (original URL only)</label>{/if}
  {#if !captured}<label>HTTP method<select bind:value={method} onchange={changed}><option>GET</option><option>POST</option></select></label><label class="checkbox"><input type="checkbox" bind:checked={reveal}/> Show manual request fields (may contain secrets)</label>{#if reveal}<label>Headers — one Name: value per line<textarea bind:value={headerText} oninput={changed} autocomplete="off" spellcheck="false" placeholder="Accept: application/octet-stream"></textarea></label>{#if method==='POST'}<label>UTF-8 POST body (maximum 1 MiB)<textarea bind:value={body} oninput={changed} autocomplete="off" spellcheck="false"></textarea></label>{/if}{/if}{/if}
  <button disabled={busy} onclick={inspect}>Check request &amp; backend</button>
  {#if browserRequest&&!captured}<p class="small muted">Complete browser request context is unavailable. Do not replay a form submission as GET.</p><label class="checkbox"><input type="checkbox" bind:checked={confirmDirect}/> I verified this is a direct GET URL, or recreated the method and body explicitly.</label>{/if}
  <AdvancedDownloadOptions {preview} bind:approved onapprovalchange={()=>{revision++;checked=false;}}/></details>{#if !checked}<p class="small muted">Check the request and backend in Advanced Download Options before starting.</p>{/if}{#if error}<div class="error-box" role="alert">{error}</div>{/if}</div>
  <footer><button disabled={busy} onclick={onclose}>Cancel</button><button class="primary" disabled={busy||!name||!source||!checked||(browserRequest&&!captured&&!confirmDirect)||!!preview?.request.bodyUnavailable} onclick={start}>{#if busy}<span class="spinner"></span>{/if}<Icon name="downloads" size={17}/> Download to Server</button></footer>
</dialog></div>
